CREATE TABLE IF NOT EXISTS product_images (id CHAR(64) PRIMARY KEY,mime VARCHAR(32) NOT NULL,content MEDIUMBLOB NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cloud_sessions (id CHAR(64) PRIMARY KEY,data MEDIUMBLOB NOT NULL,expires_at DATETIME NOT NULL,INDEX(expires_at)) ENGINE=InnoDB;
